(1802, 200170, 0, 'Methylprednisolone 8 mg  10 Tablet Triman', 0, 0, 0, 'Strip', 'Box', 10, 'OTC1', 0, 0, 2750, 0, 6000, 6000, 6000, 0, '<p>methylprednisolone 8mg/tab</p>\r\n', '<p>1. obat ini untuk mengatasi peradangan.</p>\r\n\r\n<p>2. diminum 1 tablet tiap 8 jam, sesudah makan.</p>\r\n\r\n<p>3. obat ini dapat menurunkan sistem imun, disarankan minum vitamin seperti imboost untuk menjaga daya tahan tubuh, serta perbanyak makan buah buah an yang bernutrisi.</p>\r\n\r\n<p>4. terimakasih, semoga lekas sembuh.</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-05-14', 'kayla'),
(1803, 200171, 0, 'Molacort 0.5 mg 10 Tablet', 0, 10, 0, 'Tablet', 'Box', 100, 'OTC1', 12400, 0, 138, 0, 350, 350, 350, 0, '<p>Dexamethasone 0,5mg/tab</p>\r\n', '<p>1. obat ini untuk mengatasi peradangan</p>\r\n\r\n<p>2. diminum 1 tablet tiap 8 jam, setelah makan.</p>\r\n\r\n<p>3. obat ini dapat menurunkan sistem imun, jadi di sarankan minum vitamin seperti imboost untuk menjaga daya tahan tubuh.</p>\r\n\r\n<p>4. terimakasih, semoga lekas sembuh.</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-05-14', 'kayla'),
(1804, 200172, 2, 'Intunal F 4 Tablet', 22, 0, 0, 'Strip', 'box', 25, 'OTC4', 81000, 0, 2500, 62500, 4000, 4000, 4000, 0, '<p>tiap tablet mengandung :</p>\r\n\r\n<p>paracetamol 500mg</p>\r\n\r\n<p>phenylpropanolamine HCI 15mg</p>\r\n\r\n<p>dexchlorpheniramine maleate 2mg</p>\r\n\r\n<p>dextromethorphan HBr 15mg</p>\r\n\r\n<p>guaifenesin 50mg</p>\r\n', '<p>1. obatt ini untuk meringankan gejala flu, demam, hidung tersumbat, dan batuk.</p>\r\n\r\n<p>2. diminum 1 tablet tiap 8 jam, sesudah makan.</p>\r\n\r\n<p>3. disarankan banyak minum air putih, istirahat yang cukup, dan makan buah buahan yang bernutrisi</p>\r\n\r\n<p>4. terimakasih, semoga lekas sembuh.</p>\r\n', '<p>Komposisi :<br />\r\nTiap tablet mengandung :, paracetamol 500mg, phenylpropanolamine HCI 15mg, dexchlorpheniramine maleate 2mg, dextromethorphan HBr 15mg, guaifenesin 50mg<br />\r\nIndikasi :<br />\r\nObatt ini untuk meringankan gejala flu, demam, hidung tersumbat, dan batuk.<br />\r\nEfek Samping :<br />\r\ndisarankan banyak minum air putih, istirahat yang cukup, dan makan buah buahan yang bernutrisi<br />\r\nAturan Pakai :<br />\r\ndiminum 1 tablet tiap 8 jam, sesudah makan.<br />\r\n&nbsp;</p>', 'Tablet 15 mg', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', 'product/QGrHG2TjMMHw0KlonItQ2RB1GFD5dMn9x79qpEXY.jpg', 'standar', '2026-05-14', '26'),
(1805, 8997021871097, 0, 'Freshcare Roll On Minyak Angin Kayu Putih 10 ml', 0, 1, 0, 'Botol', 'Botol', 1, 'OTC1', 11560, 0, 10907, 0, 15000, 15000, 15000, 0, '<p>menthol 20%</p>\r\n\r\n<p>champor 2%</p>\r\n\r\n<p>olive oil 10%</p>\r\n\r\n<p>cajuput oil 25%</p>\r\n\r\n<p>eucalyptus oil 25%</p>\r\n\r\n<p>oleum geranii 0.25%</p>\r\n\r\n<p>base ad 100%</p>\r\n', '<p>1. untuk meredakan perut kembung, pusing, dan masuk angin.</p>\r\n\r\n<p>2. gosokkan secukupnya pada kening, dada atau bagian tubuh yang sakit.</p>\r\n\r\n<p>3. disarankan tambah obat minum untuk membantu proses penyembuhan seperti tolak angin/paracetamol.</p>\r\n\r\n<p>4. terimakasih, semoga lekas sembuh.</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-05-15', 'kayla'),
