INSERT INTO `barang` (`id_barang`, `kd_barang`, `category_id`, `nm_barang`, `stok_barang`, `stok_buffer`, `stok_grosir`, `sat_barang`, `sat_grosir`, `konversi`, `jenisobat`, `hna`, `diskon`, `hrgsat_barang`, `hrgsat_grosir`, `hrgjual_barang`, `hrgjual_barang1`, `hrgjual_barang2`, `komisi`, `zataktif`, `indikasi`, `ket_barang`, `dosis`, `waktu`, `t30`, `t60`, `gr`, `q30`, `petugas`, `status`, `image`, `promosi`, `tgl`, `updated_by`) VALUES
(2319, 51131000223, 0, 'Nexcare Opticlude Orthoptic Eye Patch Junior', 0, 0, 0, 'Pcs', 'selected', 1, 'OTC1', 0, 0, 7500, 0, 10000, 10000, 10000, 0, '', '<p>1.&nbsp;Digunakan untuk mengobati amblyopia (mata malas) dan strabismus (mata juling) pada anak sebagai bagian dari terapi yang direkomendasikan oleh dokter mata. Patch ini membantu menutup mata yang lebih kuat sehingga mata yang lebih lemah &ldquo;latihan&rdquo; dan dapat meningkat penglihatannya.<br />\r\n2. Dipakai menutup mata yang lebih kuat selama durasi yang ditentukan oleh dokter&nbsp;<br />\r\n3.&nbsp;Jika terjadi iritasi kulit atau ruam setelah pemakaian, hentikan penggunaan dan konsultasikan ke dokter.<br />\r\n4. Terimakasih semoga sehat selalu</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-03-03', 'ryan rahma zaky'),
(2320, 51131000230, 0, 'Nexcare Opticlude Orthoptic Eye Regular', 0, 0, 0, 'box', 'selected', 1, 'OTC1', 0, 0, 7500, 0, 10000, 10000, 10000, 0, '', '<p>1.&nbsp;Eye patch ini digunakan sebagai bagian dari terapi untuk mengobati amblyopia (mata malas) dan strabismus (mata juling) dengan cara menutup mata yang lebih dominan</p>\r\n\r\n<p>2.&nbsp;Dipakai menutup mata yang lebih kuat selama durasi yang ditentukan oleh dokter</p>\r\n\r\n<p>3.&nbsp;Jika muncul iritasi kulit (kemerahan atau gatal) pada area sekitar mata, hentikan penggunaan dan konsultasikan ke dokter.&nbsp;</p>\r\n\r\n<p>4. Terimakasih semoga sehat selalu</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-03-03', 'ryan rahma zaky'),
(2321, 8992772315128, 0, 'Soffel Botol Kulit Jeruk 60 g', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC1', 8720, 0, 9340, 0, 12000, 12000, 12000, 0, '<p>Diethyltoluamide</p>\r\n', '<p>1.&nbsp;minyak kulit jeruk untuk membantu mengurangi rasa gatal dan menenangkan kulit akibat gigitan nyamuk atau iritasi ringan, oleskan tipis pada area yang gatal setelah dibersihkan, hindari kontak dengan mata/mulut, jika iritasi makin parah hentikan pemakaian dan bilas dengan air bersih</p>\r\n\r\n<p>2.&nbsp;oleskan secukupnya pada kulit yang gatal 2&ndash;3 kali sehari sesuai kebutuhan</p>\r\n\r\n<p>3. Terimakasih semoga sehat lari</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-03-04', 'ryan rahma zaky'),
(2322, 8992772215039, 0, 'Soffel Spray Geranium 80ml', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC1', 11810, 0, 12847, 0, 16000, 16000, 16000, 0, '<p>Diethyltoluamide (DEET) ~13 %</p>\r\n', '<p>1. Semprotan anti nyamuk dengan aroma geranium untuk membantu menjauhkan nyamuk, semprotkan ke kulit yang terbuka atau area sekitar tempat bersantai, hindari semprotan ke wajah/kelamin/mata, jika iritasi kulit muncul hentikan pemakaian</p>\r\n\r\n<p>2.&nbsp;semprotkan secukupnya pada kulit atau area yang ingin dilindungi dari nyamuk sesuai kebutuhan</p>\r\n\r\n<p>3. Terimkasih semoga sehat selalu</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-03-04', 'ryan rahma zaky'),
(2323, 200254, 0, 'Itraconazole 100 mg 10 Kapsul Bernofarm', 0, 0, 0, 'Strip', 'Box', 3, 'ETC1', 137000, 0, 44100, 0, 60000, 60000, 60000, 0, '<p>Itraconazole 100 mg</p>\r\n', '<p>1.&nbsp;Obat ini digunakan untuk mengatasi infeksi jamur di kulit, mulut, atau kuku. Sebaiknya diminum setelah makan untuk meningkatkan penyerapan. Jika memiliki gangguan hati atau jantung, konsultasikan dokter sebelum minum. Hindari obat ini bila sedang hamil atau menyusui tanpa petunjuk dokter. Perhatikan juga kemungkinan interaksi dengan obat lain seperti obat kolesterol atau obat jantung.</p>\r\n\r\n<p>2.&nbsp;1 kapsul setiap 24 jam</p>\r\n\r\n<p>3. Terimakasih semoga lekas sembuh</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-03-03', 'ryan rahma zaky'),
(2324, 8992759124354, 0, 'Tissue Nice 180 Sheet', 0, 0, 0, 'Pcs', 'selected', 1, 'OTC1', 0, 0, 5785, 0, 10000, 10000, 10000, 0, '', '<p style=\"text-align:justify\">1.&nbsp;tisu wajah yang digunakan untuk membersihkan debu, kotoran, atau cairan dari kulit wajah maupun tangan. Terbuat dari kertas lembut dan diproses secara higienis sehingga nyaman saat bersentuhan dengan kulit.</p>\r\n\r\n<p style=\"text-align:justify\">2.&nbsp;Usapkan tisu pada area yang ingin dibersihkan sesuai kebutuhan.</p>\r\n\r\n<p style=\"text-align:justify\">3. Terimakasih semoga sehat selalu</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-03-03', 'ryan rahma zaky'),
(2325, 200255, 0, 'Tissue Paseo 250 Sheet', 0, 0, 0, 'Pcs', 'selected', 1, 'OTC1', 0, 0, 10183, 0, 13500, 13500, 13500, 0, '', '<p style=\"text-align:justify\">1.&nbsp;tisu wajah yang digunakan untuk membersihkan debu, kotoran, atau cairan dari kulit wajah maupun tangan. Terbuat dari kertas lembut dan diproses secara higienis sehingga nyaman saat bersentuhan dengan kulit.</p>\r\n\r\n<p style=\"text-align:justify\">2.&nbsp;Usapkan tisu pada area yang ingin dibersihkan sesuai kebutuhan.</p>\r\n\r\n<p style=\"text-align:justify\">3. Terimakasih semoga sehat selalu</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-03-03', 'ryan rahma zaky'),
(2326, 8995230702430, 0, 'Tissue See - U 250 Sheet', 0, 0, 0, 'Pcs', 'selected', 1, 'OTC1', 0, 0, 6999, 0, 9000, 9000, 9000, 0, '', '<p style=\"text-align:justify\">1.&nbsp;tisu wajah yang digunakan untuk membersihkan debu, kotoran, atau cairan dari kulit wajah maupun tangan. Terbuat dari kertas lembut dan diproses secara higienis sehingga nyaman saat bersentuhan dengan kulit.</p>\r\n\r\n<p style=\"text-align:justify\">2.&nbsp;Usapkan tisu pada area yang ingin dibersihkan sesuai kebutuhan.</p>\r\n\r\n<p style=\"text-align:justify\">3. Terimakasih semoga sehat selalu</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-03-03', 'ryan rahma zaky'),
