(2517, 8994805091757, 0, 'Lansoprazole 30 mg 10 Kapsul HJ', 10, 0, 0, 'Strip', 'box', 10, 'ETC1', 120000, 0, 7500, 75000, 18000, 18000, 18000, 2000, '', '', '<p>Komposisi :<br />\r\nLansoprazole 30 mg<br />\r\nIndikasi :<br />\r\nMengatasi tukak lambung, tukak duodenum, GERD (refluks asam lambung), dan infeksi H. pylori (kombinasi dengan antibiotik)<br />\r\nEfek Samping :<br />\r\nSakit kepala, diare, mual, nyeri perut, konstipasi<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kapsul sehari, sebaiknya sebelum makan pagi, ditelan utuh tanpa dikunyah, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', NULL, '0'),
(2518, 200304, 0, 'Amoxicillin 500 mg Kaplet Pharma Lab', 0, 0, 0, 'Strip', 'Box', 10, 'ETC1', 55000, 0, 5800, 0, 8000, 8000, 8000, 0, '<p><span class=\"c1\">amoxicillin 500mg </span></p>', '<p><span class=\"c1\">1. obat ini mengandung antibiotik.</span><br>\n<span class=\"c1\">2. sesuai resep dokter</span><br>\n<span class=\"c1\">3. perbanyak minum air putih, konsumsi makanan tinggi protein untuk mempercepat proses penyembuhan.</span><br>\n<span class=\"c1\">4. terimakasih sehat selalu</span></p>', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', NULL, 'siska septiana'),
