(3404, 200714, 0, 'Gentamicin Cream  5 g Bernofarm', 0, 0, 0, 'Tube', 'Box', 24, 'OTC3', 75000, 0, 2428, 0, 5000, 5000, 5000, 0, '<p><span style=\"font-family:inter,sans-serif; font-size:12px\">Gentamicin base 1 mg (0.1%).</span></p>\r\n', '<p>1.&nbsp;<span style=\"font-family:inter,sans-serif; font-size:12px\">Untuk pengobatan infeksi kulit&nbsp;</span>yang di sebabkan oleh bakteri</p>\r\n\r\n<p>2. 3 kali sehari di oleskan tipis tipis&nbsp;</p>\r\n\r\n<p>3.&nbsp;Penggunaan jangka panjang atau area luas harus diawasi untuk menghindari resistensi bakteri</p>\r\n\r\n<p>4. terimakasih,semoga lekas sembuh</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-05-09', 'ahmad fathi nurrodi yusuf'),
(3405, 200715, 0, 'Thiamycin 500 mg 10 Kapsul', 0, 0, 0, 'Strip', 'Box', 10, 'OTC1', 564000, 0, 43823, 0, 72000, 72000, 72000, 0, '<p><span style=\"background-color:rgb(249, 249, 249); font-family:source sans pro,helvetica neue,helvetica,arial,sans-serif; font-size:14px\">Thiamycin 500 mg&nbsp;</span></p>\r\n', '<p><span style=\"font-size:14px\">1<span style=\"font-size:16px\">.&nbsp;<span style=\"font-family:inter,sans-serif\">infeksi serius yang disebabkan oleh bakteri yang rentan, seperti demam tifoid dan infeksi saluran kemih berat.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:16px\">2. minum 3 kali sehari 1 tablet setelah makan,habiskan</span></p>\r\n\r\n<p><span style=\"font-size:16px\">3. minum sesuai anjuran dokter dan banyak makan makanan tinggi protein&nbsp;</span></p>\r\n\r\n<p><span style=\"font-size:16px\">4. terimakasih, semoga lekas sembuh&nbsp;</span></p>\r\n\r\n<p>&nbsp;</p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-05-09', 'ahmad fathi nurrodi yusuf'),
