(5709, 2014195, 0, 'Pregabalin 150 mg 1 Kapsul Dexa', 0, 0, 0, 'Kapsul', 'Box', 30, 'OTC1', 270000, 0, 8042, 299700, 12000, 12000, 12000, 0, '<p>&nbsp;Pregabalin 150 mg</p>\r\n', '<p>1.&nbsp;meredakan nyeri saraf,mengatasi kejang parsial, gangguan kecemasan</p>\r\n\r\n<p>2.&nbsp;<span style=\"font-family:inter,sans-serif; font-size:12px\">2 kali sehari.,Sebelum atau sesudah makan, dapat bersama makanan untuk mengurangi ketidak-nyamanan saluran cerna.</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">3.&nbsp;pusing dan rasa kantuk. Efek samping lain yang mungkin terjadi meliputi mulut kering, penglihatan kabur, penambahan berat badan, dan edema perifer (bengkak pada tangan atau kaki).</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">4. terimakasih semoga lekas sembuh</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-06-19', 'ahmad fathi nurrodi yusuf'),
(5710, 2014196, 0, 'Cefixime 100 mg 10 Kapsul Bernofarm', 0, 0, 0, 'Blister', 'Box', 10, 'OTC1', 225000, 0, 12488, 249750, 30000, 30000, 30000, 0, '<p>Cefixime 100 mg&nbsp;</p>\r\n', '<p>1.&nbsp;<span style=\"font-family:inter,sans-serif; font-size:12px\">Infeksi saluran kemih tanpa komplikasi, otitis media,</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">2.&nbsp;&nbsp;diberikan dua kali sehari.Dikonsumsi sebelum atau sesudah makan. Dapat diberikan bersama makanan untuk mengurangi rasa tidak nyaman pada saluran pencernaan.</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">3.&nbsp;Syok, Hipersensitivitas, Hematologi, Hati, Ginjal, Saluran Cerna, Pernapasan, Perubahan flora bakteri, Defisiensi vitamin, Pengaruh terhadap tes laboratorium</span></p>\r\n\r\n<p><font face=\"inter, sans-serif\"><span style=\"font-size:12px\">4. terimakasih semoga lekas sembuh</span></font></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-06-19', 'ahmad fathi nurrodi yusuf'),
(5711, 8992001880656, 0, 'Cefadroxil 125 mg/5 ml Dry Syrup 60 ml Bernofarm', 0, 0, 0, 'Botol', 'Botol', 1, 'OTC1', 15000, 0, 11489, 16650, 15000, 15000, 15000, 0, '<p><span style=\"font-family:inter,sans-serif; font-size:12px\">Cefadroksil 125 mg</span></p>\r\n', '<p>1.&nbsp;<span style=\"font-family:inter,sans-serif; font-size:12px\">Mengatasi infeksi saluran pernafasan, saluran kemih dan kelamin serta infeksi kulit dan jaringan lunak</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">2. 2 kali sehari setelah makan</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">3.&nbsp;Gangguan umum dan kondisi tempat pemberian: Jarang, demam.</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">4. terimakasih semoga lekas sembuh</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-06-19', 'ahmad fathi nurrodi yusuf'),
