(5723, 2014203, 0, 'Celecoxib 200 mg 10 Kapsul HJ', 0, 0, 0, 'Blister', 'Box', 5, 'OTC1', 250000, 0, 52725, 277500, 70000, 70000, 70000, 0, '<p><span style=\"font-family:inter,sans-serif; font-size:12px\">Celecoxib 200 mg</span></p>\r\n', '<p>1.&nbsp;<span style=\"font-family:inter,sans-serif; font-size:12px; white-space:pre-line\">Meredakan tanda dan gejala Osteoarthritis (OA), Rheumatoid arthritis (RA) &amp; Ankilosing Spondilitis pada orang dewasa serta Artritis idiopatik juvenil pada anak-anak.</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px; white-space:pre-line\">2.&nbsp;</span><span style=\"font-family:inter,sans-serif; font-size:12px\">1 kali sehari 1 kapsul atau 100 mg, 2 kali sehari 1 kapsul. Max.400 mg per hari.setelaj makan</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">3.&nbsp;Mual, sakit perut, diare, dispepsia, perut kembung, muntah, disfagia, GERD, sindrom iritasi usus besar</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">4. terimakasih semoga lekas sembuh</span></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-06-19', 'ahmad fathi nurrodi yusuf'),
(5724, 2014204, 0, 'Celecoxib 200 mg 10 Kapsul Dexa', 0, 0, 0, 'Blister', 'Box', 3, 'OTC1', 150000, 0, 52725, 166500, 70000, 70000, 70000, 0, '<p><span style=\"font-family:inter,sans-serif; font-size:12px\">Celecoxib 200 mg</span></p>\r\n', '<p>1.&nbsp;<span style=\"font-family:inter,sans-serif; font-size:12px\">Meredakan tanda dan gejala Osteoarthritis (OA), Rheumatoid arthritis (RA) &amp; Ankilosing Spondilitis pada orang dewasa serta Artritis idiopatik juvenil pada anak-anak.</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">2.&nbsp;200 mg, 1 kali sehari 1 kapsul atau 100 mg, 2 kali sehari 1 kapsul. Max.400 mg per hari.</span></p>\r\n\r\n<p><span style=\"font-family:inter,sans-serif; font-size:12px\">3.&nbsp;Mual, sakit perut, diare, dispepsia, perut kembung, muntah, disfagia, GERD, sindrom iritasi usus besar</span></p>\r\n\r\n<p><font face=\"inter, sans-serif\"><span style=\"font-size:12px\">4. terimakasih,semoga lekas sembuh</span></font></p>\r\n', '', '', '0000-00-00 00:00:00', 0, 0, 0, 0, '', 'active', '', 'terlaris', '2026-06-19', 'ahmad fathi nurrodi yusuf'),
